-- CVStudio · Biblioteca modular avanzada v3
-- 18 perfiles sectoriales construidos desde 21 módulos y 90 consignas.

create table if not exists public.modulos_evaluacion (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  titulo text not null,
  categoria text not null,
  descripcion text,
  competencias text[] not null default '{}',
  preguntas jsonb not null default '[]'::jsonb check (jsonb_typeof(preguntas)='array'),
  fuentes jsonb not null default '[]'::jsonb,
  activo boolean not null default true,
  creado_en timestamptz not null default now(),
  actualizado_en timestamptz not null default now()
);

alter table public.modulos_evaluacion enable row level security;
revoke all on table public.modulos_evaluacion from anon;
grant select,insert,update,delete on table public.modulos_evaluacion to authenticated;
drop policy if exists "Dirección administra módulos de evaluación" on public.modulos_evaluacion;
create policy "Dirección administra módulos de evaluación" on public.modulos_evaluacion
for all to authenticated
using ((select auth.uid()) in ('3a8b4d50-305a-4da5-9fde-64bd2c8ed68d'::uuid,'6a608be9-da9f-4fb6-941c-4a14ac62a865'::uuid))
with check ((select auth.uid()) in ('3a8b4d50-305a-4da5-9fde-64bd2c8ed68d'::uuid,'6a608be9-da9f-4fb6-941c-4a14ac62a865'::uuid));

insert into public.modulos_evaluacion(slug,titulo,categoria,descripcion,competencias,preguntas,fuentes) values
('razonamiento-datos','Razonamiento y análisis de datos','Núcleo','Interpretación, cálculo aplicado y toma de decisiones con información incompleta.',array['Razonamiento numérico','Interpretación de datos','Resolución de problemas'],$q$[
{"id":"rd1","module":"razonamiento-datos","dimension":"Análisis de datos","difficulty":"alta","context":"Un equipo procesó 420 casos: 168 en el turno A, 147 en el B y el resto en el C. Las incidencias fueron 4, 3 y 5 respectivamente.","text":"¿Qué turno tuvo la mayor tasa de incidencias, no la mayor cantidad absoluta?","options":[{"value":"A","label":"Turno A"},{"value":"B","label":"Turno B"},{"value":"C","label":"Turno C"},{"value":"D","label":"A y C empatan"}],"correct":"C","explanation":"C procesó 105 casos y tuvo 5 incidencias: 4,76%, superior a A y B."},
{"id":"rd2","module":"razonamiento-datos","dimension":"Razonamiento numérico","difficulty":"alta","context":"Una tarea estándar demanda 12 minutos. Tras una mejora, el tiempo baja 15%, pero se agrega un control final de 90 segundos.","text":"¿Cuál es el nuevo tiempo total por tarea?","options":[{"value":"A","label":"9 min 42 s"},{"value":"B","label":"10 min 12 s"},{"value":"C","label":"11 min 42 s"},{"value":"D","label":"12 min 30 s"}],"correct":"C"},
{"id":"rd3","module":"razonamiento-datos","dimension":"Planificación","difficulty":"alta","context":"Hay 7 horas útiles. Las tareas P, Q y R duran 110, 85 y 70 minutos. P debe hacerse antes que R. Además hay dos controles de 35 minutos y una contingencia reservada de 40 minutos.","text":"¿Qué afirmación es correcta?","options":[{"value":"A","label":"No entran todas las tareas"},{"value":"B","label":"Entran y quedan 35 minutos libres"},{"value":"C","label":"Entran y quedan 45 minutos libres"},{"value":"D","label":"Solo entran si R se realiza antes que P"}],"correct":"C"},
{"id":"rd4","module":"razonamiento-datos","dimension":"Inferencia","difficulty":"alta","context":"Todo registro validado tiene responsable identificado. Algunos registros con responsable identificado todavía no fueron auditados. El registro K fue validado.","text":"¿Qué conclusión es necesariamente válida?","options":[{"value":"A","label":"K fue auditado"},{"value":"B","label":"K tiene responsable identificado"},{"value":"C","label":"K no presenta errores"},{"value":"D","label":"K es uno de los registros no auditados"}],"correct":"B"},
{"id":"rd5","module":"razonamiento-datos","dimension":"Análisis de datos","difficulty":"media-alta","context":"Un indicador pasa de 8% a 6% y el volumen permanece estable.","text":"¿Cómo debe describirse correctamente el cambio?","options":[{"value":"A","label":"Bajó 2%"},{"value":"B","label":"Bajó 2 puntos porcentuales, equivalente a una reducción relativa del 25%"},{"value":"C","label":"Bajó 25 puntos porcentuales"},{"value":"D","label":"Mejoró 75%"}],"correct":"B"},
{"id":"rd6","module":"razonamiento-datos","dimension":"Criterio analítico","difficulty":"alta","context":"Dos informes muestran totales distintos para el mismo período. Uno fue exportado a las 10:00 y otro a las 15:00; el sistema admite actualizaciones retroactivas.","text":"¿Cuál es el primer paso más sólido?","options":[{"value":"A","label":"Usar el total mayor"},{"value":"B","label":"Promediar ambos"},{"value":"C","label":"Verificar corte, filtros, versión y movimientos incorporados entre exportaciones"},{"value":"D","label":"Descartar los dos informes"}],"correct":"C"}
]$q$::jsonb,'["https://www.onetcenter.org/content.html","https://esco.ec.europa.eu/en/classification/skill_main"]'::jsonb),
('atencion-instrucciones','Atención, precisión e instrucciones','Núcleo','Control de detalles, reglas condicionales y trazabilidad.',array['Atención selectiva','Precisión','Seguimiento de instrucciones'],$q$[
{"id":"ai1","module":"atencion-instrucciones","dimension":"Seguimiento de instrucciones","difficulty":"alta","context":"Regla: si el código comienza con R y termina en número par, va a Revisión; si contiene X, va a Excepción, aun cuando cumpla la primera regla.","text":"¿Dónde se clasifica R-31X-8?","options":[{"value":"A","label":"Revisión"},{"value":"B","label":"Excepción"},{"value":"C","label":"Archivo"},{"value":"D","label":"No puede determinarse"}],"correct":"B"},
{"id":"ai2","module":"atencion-instrucciones","dimension":"Precisión","difficulty":"alta","text":"Seleccioná la única cadena idéntica a AR7-09I1-BQ5 (la tercera posición es el número 7 y la sexta es la letra I).","options":[{"value":"A","label":"AR7-09I1-BQ5"},{"value":"B","label":"AR7-0911-BQ5"},{"value":"C","label":"A7R-09I1-BQ5"},{"value":"D","label":"AR7-09I1-8Q5"}],"correct":"A"},
{"id":"ai3","module":"atencion-instrucciones","dimension":"Control de calidad","difficulty":"alta","context":"La instrucción exige validar identidad, fecha, importe y autorización. El registro tiene identidad, fecha e importe correctos, pero la autorización está vencida.","text":"¿Qué estado corresponde?","options":[{"value":"A","label":"Aprobado porque tres campos son correctos"},{"value":"B","label":"Pendiente de regularización; no debe aprobarse"},{"value":"C","label":"Aprobado con una nota informal"},{"value":"D","label":"Eliminado sin dejar registro"}],"correct":"B"},
{"id":"ai4","module":"atencion-instrucciones","dimension":"Priorización","difficulty":"media-alta","context":"A: vence hoy y afecta seguridad. B: vence hoy y afecta un reporte interno. C: vence mañana y bloquea a un cliente. D: no vence y lleva 5 minutos.","text":"Sin otra información, ¿qué orden inicial es más defendible?","options":[{"value":"A","label":"D, B, C, A"},{"value":"B","label":"A, C, B, D"},{"value":"C","label":"B, D, A, C"},{"value":"D","label":"C, A, D, B"}],"correct":"B"},
{"id":"ai5","module":"atencion-instrucciones","dimension":"Trazabilidad","difficulty":"media-alta","context":"Descubrís que cargaste un dato incorrecto en un registro ya utilizado por otra área.","text":"¿Cuál es la respuesta más completa?","options":[{"value":"A","label":"Sobrescribirlo y no informar"},{"value":"B","label":"Crear otro registro sin relacionarlos"},{"value":"C","label":"Corregir según procedimiento, conservar trazabilidad y avisar a quienes pudieron verse afectados"},{"value":"D","label":"Esperar a que otra persona lo encuentre"}],"correct":"C"},
{"id":"ai6","module":"atencion-instrucciones","dimension":"Comprensión","difficulty":"alta","context":"Procedimiento: tomar una muestra inicial y luego una cada 45 minutos mientras la línea esté activa. La línea operó de 08:10 a 11:20 sin interrupciones.","text":"¿Cuántas muestras correspondían?","options":[{"value":"A","label":"4"},{"value":"B","label":"5"},{"value":"C","label":"6"},{"value":"D","label":"7"}],"correct":"B"}
]$q$::jsonb,'["https://www.onetcenter.org/content.html"]'::jsonb),
('criterio-entrevista','Criterio laboral y entrevista','Núcleo','Juicio situacional, comunicación, ética y respuestas con evidencia.',array['Juicio situacional','Comunicación','Autoconocimiento'],$q$[
{"id":"ce1","module":"criterio-entrevista","dimension":"Criterio laboral","difficulty":"alta","context":"Tu responsable pide acelerar una entrega. Al revisar, detectás que falta una validación obligatoria y que omitirla podría generar un error importante.","text":"¿Qué respuesta muestra mejor criterio?","options":[{"value":"A","label":"Entregar sin validar para cumplir el horario","score":0},{"value":"B","label":"Negarse sin explicar ni proponer alternativas","score":1},{"value":"C","label":"Explicar el riesgo, estimar el tiempo de validación y acordar una alternativa segura","score":3},{"value":"D","label":"Validar en secreto y avisar después si surge un problema","score":2}]},
{"id":"ce2","module":"criterio-entrevista","dimension":"Trabajo en equipo","difficulty":"alta","context":"Un compañero experimentado propone un atajo habitual que contradice el procedimiento vigente. No hubo incidentes anteriores.","text":"¿Cómo actuarías?","options":[{"value":"A","label":"Aceptar porque tiene más experiencia","score":0},{"value":"B","label":"Revisar el procedimiento con él, explicar la diferencia y escalar la duda antes de aplicarlo","score":3},{"value":"C","label":"Denunciarlo inmediatamente sin conversar","score":1},{"value":"D","label":"Aplicarlo solo esta vez y documentarlo","score":1}]},
{"id":"ce3","module":"criterio-entrevista","dimension":"Comunicación","difficulty":"media-alta","context":"Recibís dos instrucciones incompatibles de personas con autoridad similar y el plazo es corto.","text":"¿Cuál es la mejor intervención?","options":[{"value":"A","label":"Elegir una al azar y avanzar","score":0},{"value":"B","label":"Esperar hasta que se resuelva solo","score":0},{"value":"C","label":"Exponer la contradicción, el impacto y pedir una prioridad explícita dejando registro","score":3},{"value":"D","label":"Hacer parcialmente ambas sin avisar","score":1}]},
{"id":"ce4","module":"criterio-entrevista","dimension":"Integridad","difficulty":"alta","context":"Cometiste un error que todavía puede corregirse, pero informarlo podría generar una demora visible.","text":"¿Qué opción es más profesional?","options":[{"value":"A","label":"Corregirlo silenciosamente si nadie lo notó","score":1},{"value":"B","label":"Informarlo con hechos, contener el impacto y proponer la corrección","score":3},{"value":"C","label":"Atribuirlo a una falla del sistema","score":0},{"value":"D","label":"Esperar a confirmar si tendrá consecuencias","score":0}]},
{"id":"ce5","module":"criterio-entrevista","dimension":"Entrevista estructurada","difficulty":"alta","type":"text","text":"Relatá una situación real en la que tuviste que priorizar tareas bajo presión. Indicá contexto, criterios utilizados, acciones, resultado y qué cambiarías hoy.","rubric":["Contexto verificable","Criterio de prioridad","Acciones propias","Resultado","Aprendizaje"]},
{"id":"ce6","module":"criterio-entrevista","dimension":"Entrevista estructurada","difficulty":"alta","type":"text","text":"Describí un error laboral o académico del que te hayas hecho responsable. ¿Cómo lo detectaste, a quién informaste, cómo lo corregiste y qué prevención implementaste?","rubric":["Responsabilidad sin excusas","Comunicación","Corrección","Prevención"]}
]$q$::jsonb,'["https://www.siop.org/tip-article/is-cognitive-ability-the-best-predictor-of-job-performance-new-research-says-its-time-to-think-again/"]'::jsonb),

