), construidas as (
  select p.*,
    (select coalesce(jsonb_agg(q.question),'[]'::jsonb)
     from public.modulos_evaluacion m cross join lateral jsonb_array_elements(m.preguntas) q(question)
     where m.slug in ('razonamiento-datos','atencion-instrucciones','criterio-entrevista',p.modulo)) as banco,
    (select coalesce(jsonb_agg(distinct c.competencia),'[]'::jsonb)
     from public.modulos_evaluacion m cross join lateral unnest(m.competencias) c(competencia)
     where m.slug in ('razonamiento-datos','atencion-instrucciones','criterio-entrevista',p.modulo)) as competencias,
    (select coalesce(jsonb_agg(distinct f.fuente),'[]'::jsonb)
     from public.modulos_evaluacion m cross join lateral jsonb_array_elements_text(m.fuentes) f(fuente)
     where m.slug in ('razonamiento-datos','atencion-instrucciones','criterio-entrevista',p.modulo)) as fuentes
  from perfiles p
)
insert into public.plantillas_evaluacion(slug,titulo,tipo,descripcion,sector,nivel,duracion_minutos,cantidad_preguntas,version_contenido,competencias,fuentes,preguntas,activa)
select slug,titulo,tipo,descripcion,sector,'Avanzado',duracion,cantidad,'3.0',competencias,fuentes,banco,true from construidas
on conflict(slug) do update set titulo=excluded.titulo,tipo=excluded.tipo,descripcion=excluded.descripcion,
sector=excluded.sector,nivel=excluded.nivel,duracion_minutos=excluded.duracion_minutos,cantidad_preguntas=excluded.cantidad_preguntas,
version_contenido=excluded.version_contenido,competencias=excluded.competencias,fuentes=excluded.fuentes,preguntas=excluded.preguntas,
activa=true,actualizado_en=now();

